import{c as a,Q as t,j as i,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Red Teaming Language Models with Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2202.03286","title":"Red Teaming Language Models with Language Models","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2202.03286,"authors":["Ethan Perez","Saffron Huang","Francis Song","Trevor Cai","Roman Ring","John Aslanides","Amelia Glaese","Nat McAleese","Geoffrey Irving"],"pdf_path":"pdfs/2202.03286.pdf","published_date":"2022-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2022-02-07-red-teaming-language-models-2202-03286.md","filePath":"research/papers/2022-02-07-red-teaming-language-models-2202-03286.md","lastUpdated":1785909234000}'),n={name:"research/papers/2022-02-07-red-teaming-language-models-2202-03286.md"};function o(s,e,l,d,h,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="red-teaming-language-models-with-language-models" tabindex="-1">Red Teaming Language Models with Language Models <a class="header-anchor" href="#red-teaming-language-models-with-language-models" aria-label="Permalink to &quot;Red Teaming Language Models with Language Models&quot;">​</a></h1><p><strong>Authors:</strong> Ethan Perez, Saffron Huang, Francis Song, Trevor Cai, Roman Ring, John Aslanides, Amelia Glaese, Nat McAleese, Geoffrey Irving</p><p><strong>Year:</strong> 2022</p><p><strong>Venue:</strong> arXiv preprint (Anthropic / DeepMind collaboration; widely cited as foundational LLM red teaming work)</p><p><strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2202.03286" target="_blank" rel="noreferrer">https://arxiv.org/abs/2202.03286</a></p><hr><h2 id="full-abstract" tabindex="-1">Full Abstract <a class="header-anchor" href="#full-abstract" aria-label="Permalink to &quot;Full Abstract&quot;">​</a></h2><p>Language models (LMs) often cannot be deployed because of their potential to harm users in hard-to-predict ways. Prior work has relied on human annotators to manually construct a limited set of adversarial test cases, which is expensive, limited in scale, and does not systematically cover the space of potential harms. We propose to instead use language models to automatically generate test cases that expose harmful behaviors in target LMs, enabling far more extensive and systematic safety evaluation. We generate test cases using a variety of methods including zero-shot generation, few-shot generation, supervised learning, and reinforcement learning, allowing us to control test case difficulty and diversity. Applied to a 280 billion parameter chatbot, our approach discovers a wide range of harmful behaviors including offensive replies, data leakage, and multi-turn harms, all at far greater scale and breadth than prior human-annotated approaches. We release our code and models to facilitate further research on LM safety evaluation.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>LM-as-red-teamer paradigm:</strong> Pioneered the approach of using a language model to automatically generate adversarial test cases against a target LM, enabling scalable safety evaluation without expensive human annotation at each step.</li><li><strong>Multi-method attack generation:</strong> Introduced a spectrum of test case generation strategies — zero-shot prompting, few-shot prompting, supervised learning on human-curated examples, and reinforcement learning with a classifier reward — providing control over attack diversity and difficulty.</li><li><strong>Diverse harm discovery at scale:</strong> Applied to a 280B-parameter chatbot, the method uncovered offensive replies, harmful demographic stereotypes, leaked training data (including real phone numbers), and emergent multi-turn conversational harms.</li><li><strong>RL-controlled diversity:</strong> Demonstrated that RL-trained red teaming models, rewarded for eliciting harmful outputs, discover qualitatively different (and harder) attacks compared to zero/few-shot methods, establishing the importance of diversity-maximizing red teaming.</li><li><strong>Classifier-based harm detection pipeline:</strong> Introduced systematic at-scale harm detection using trained classifiers, enabling evaluation of millions of generated test cases that would be infeasible for human review.</li><li><strong>Foundational methodology:</strong> Established the conceptual and experimental template — red LM, target LM, harm classifier, diversity metrics — that all subsequent automated red teaming frameworks (PAIR, TAP, WildTeaming, HarmBench) build upon.</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>The core framework involves three components: a red LM that generates test prompts, a target LM that responds to those prompts, and a harm classifier that labels responses as harmful or benign. The red LM is prompted or trained to generate diverse, adversarial inputs, while the harm classifier provides a scalar signal indicating whether the target&#39;s response contains harmful content. This setup decouples the attack generation problem from the harm detection problem, allowing each component to be independently improved.</p><p>Four generation strategies are explored in ascending order of sophistication. Zero-shot generation prompts the red LM to produce harmful questions with no examples. Few-shot generation conditions on a small set of human-curated harmful queries to guide style and topic. Supervised learning fine-tunes the red LM on human-annotated adversarial examples, specializing it toward productive attack patterns. Reinforcement learning uses the harm classifier as a reward function, training the red LM via policy gradient to maximize the probability of eliciting harmful responses while maintaining lexical diversity through entropy bonuses. The RL approach is most powerful but also most prone to mode collapse without diversity regularization.</p><p>Multi-turn harm evaluation extends the framework beyond single-turn exchanges. The red LM generates entire conversation prefixes that guide the target chatbot toward harmful behaviors through progressive context manipulation — a key finding being that harms can emerge in turn 3 or 4 of a conversation even when individual turns appear benign, exploiting the conversational context accumulation of transformer-based chatbots.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li>Zero-shot red teaming already uncovers thousands of offensive outputs from the 280B chatbot; RL-trained red teaming discovers qualitatively harder cases that zero-shot and few-shot methods miss.</li><li>Training data leakage is confirmed: the red LM elicits verbatim phone numbers and other personally identifiable information from the target chatbot, establishing training data memorization as a concrete harm vector.</li><li>Harmful stereotype generation is widespread: the target chatbot produces disparaging associations for dozens of demographic groups when appropriately prompted, revealing alignment gaps in safety fine-tuning.</li><li>Multi-turn attacks succeed in eliciting harmful content even from a chatbot that reliably refuses single-turn harmful requests — establishing conversational context manipulation as a distinct and underappreciated attack surface.</li><li>RL-trained red teaming achieves higher harmful response rates per query than zero-shot or few-shot methods, but requires more careful diversity regularization to avoid degenerate repetitive outputs.</li><li>Harm classifier accuracy is sufficient for large-scale automated evaluation but introduces false positive/negative rates that create noise in aggregate statistics — motivating later work (HarmBench) to improve judge reliability.</li></ul><hr><h2 id="limitations-and-future-work" tabindex="-1">Limitations and Future Work <a class="header-anchor" href="#limitations-and-future-work" aria-label="Permalink to &quot;Limitations and Future Work&quot;">​</a></h2><ul><li><strong>Classifier dependence:</strong> The approach is limited by the quality of the harm classifier; errors in harm detection propagate directly into red teaming evaluation quality and RL reward signal fidelity.</li><li><strong>Single-model red teamer:</strong> The red LM is a single model; adversarial diversity is limited by its prior and training distribution, potentially missing harm vectors outside its coverage.</li><li><strong>Evaluation at one scale:</strong> Results are reported for a single 280B-parameter target chatbot; generalization to models of different scales, architectures, and training regimes is not systematically characterized.</li><li><strong>RL instability:</strong> Reinforcement learning for red teaming is sensitive to hyperparameters and prone to reward hacking (the red LM learns to fool the classifier rather than elicit genuine harm); robust RL-based red teaming remains an open problem.</li><li><strong>No defense evaluation:</strong> The paper focuses entirely on attack generation and does not evaluate how discovered harms can be mitigated or whether safety fine-tuning on discovered cases improves robustness.</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>This paper is the foundational reference for automated red teaming — the paper that established the LM-red-teams-LM paradigm that all subsequent automated safety evaluation work inherits:</p><ul><li><strong>Scalability inflection point:</strong> By replacing human annotation with LM-generated test cases, the paper demonstrated that safety evaluation can scale to millions of queries, fundamentally changing what comprehensive safety assessment looks like.</li><li><strong>Multi-turn safety gap:</strong> The multi-turn harm discovery is practically critical — chatbot deployments rarely evaluate multi-turn conversational safety, yet this paper shows harmful behaviors can emerge specifically from conversation accumulation.</li><li><strong>Training data leakage evidence:</strong> The phone number leakage result provided early empirical grounding for memorization-based privacy risks, influencing data governance practices and model auditing standards.</li><li><strong>RL diversity insight:</strong> The finding that RL-trained red teamers find qualitatively different attacks than prompting-based methods established diversity maximization as a first-class objective in red teaming — not just attack success rate.</li><li><strong>Template for tooling:</strong> Every major red teaming tool published after 2022 (PAIR, TAP, AutoDAN, HarmBench, WildTeaming) traces its conceptual lineage to this paper&#39;s three-component framework.</li></ul>',26)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
